                                break;

                        case X86_INS_MOVABS:
                        case X86_INS_MOV:
                                // do not print number in negative form
                                SStream_concat(O, "$0x%"PRIx64, imm);
                                break;

                        case X86_INS_IN:
                        case X86_INS_OUT:
                        case X86_INS_INT:
                                // do not print number in negative form
                                imm = imm & 0xff;
                                if (imm >= 0 && imm <= HEX_THRESHOLD)
                                        SStream_concat(O, "$%u", imm);
                                else {
                                        SStream_concat(O, "$0x%x", imm);
                                }
                                break;

                        case X86_INS_LCALL:
                        case X86_INS_LJMP:
                        case X86_INS_JMP:
                                // always print address in positive form
                                if (OpNo == 1) {        // selector is ptr16
                                        imm = imm & 0xffff;
                                        opsize = 2;
                                } else
                                        opsize = 4;
                                SStream_concat(O, "$0x%"PRIx64, imm);
                                break;

                        case X86_INS_AND:
                        case X86_INS_OR:
                        case X86_INS_XOR:
                                // do not print number in negative form
                                if (imm >= 0 && imm <= HEX_THRESHOLD)
                                        SStream_concat(O, "$%u", imm);
                                else {
                                        imm = arch_masks[opsize? opsize : MI->imm_size] & imm;
